function LadderStruggleBattleAbstractDialog:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

function LadderStruggleBattleAbstractDialog:InitComponent()
    SetButtonAction(self.Btn_ExitBtn, Bind(self, self.OnExitBtnClick))
    SetButtonAction(self.Btn_Statistic, Bind(self, self.OnStatisticBtnClick))
    KTool.SetActive(self.Btn_Statistic, not self.noStatistic)

    self.playerTeamLTArray = {}
    for i = 0, 2, 1 do
        local playerTeamRT = self.RT_TeamGroup:GetChild(i)
        if not IsNull(playerTeamRT) then
            local LB_playerTeam = GetLuaBehaviour(playerTeamRT.gameObject, PlayerTeamLuaPath)
            table.insert(self.playerTeamLTArray, LB_playerTeam.Env)
            LB_playerTeam.Env:SetSystem(self.systemName)
        end
    end

    if isNotNull(self.Btn_ExitBtn)
    and self.exitBtnText then
        CfUtils.FillText(self.Btn_ExitBtn.transform:Find("Text"), self.exitBtnText)
    end
end

function LadderStruggleBattleAbstractDialog:InitListener()
    local directShowBattleEnd = self.controller.Argument.parameters.directShowBattleEnd
    if directShowBattleEnd then return end

    self._eventOnRoleDead = Events.AddListener(Constants.EventNames.UIQuickBattleRoleDead, Bind(self, self.OnRoleDead))
end

function LadderStruggleBattleAbstractDialog:RemoveListener()
    if self._eventOnRoleDead then
