--- 初始化总的战斗状态组件
function LadderStruggleBattleAbstractDialog:SetTotalBattleState(state)
    KTool.SetActive(self.RT_BattleResult, false)
    KTool.SetActive(self.RT_BattleRunning, false)
    KTool.SetActive(self.RT_BattleResultWin, false)
    KTool.SetActive(self.RT_BattleResultLose, false)

    if state == BattleState.Win then
        KTool.SetActive(self.RT_BattleResult, true)
        KTool.SetActive(self.RT_BattleResultWin, true)
    elseif state == BattleState.Lose then
        KTool.SetActive(self.RT_BattleResult, true)
        KTool.SetActive(self.RT_BattleResultLose, true)
        self.Animator_Result:Play("Lose")
    elseif state == BattleState.Running then
        KTool.SetActive(self.RT_BattleRunning, true)
    end
end

