--- 直接显示战斗结果
function LadderStruggleBattleAbstractDialog:ShowBattleResult()
    self:SetTotalBattleResult()
    self:SetTeamBattleResult()
    self:ShowExitBtn()
end

--- 表演快速战斗
function LadderStruggleBattleAbstractDialog:ShowBattle()
    self:SetTotalBattleState(BattleState.Running)
    
    self.showCo = cs_coroutine.start(function()
        local struggleData = LadderStruggleMgr.struggleData
        for i, waveData in ipairs(struggleData) do
            if i > LadderStruggleMgr.totalSessionCount then
                self:SetTeamBattleState(i, 3)
            else
                self.curWave = i
                -- print("[大乱斗] init data", table.dump(waveData.initData, nil, 5))
                cs_coroutine.yield_return(QuickBattleViewMgr:ShowRecordData(waveData.recordData))
                -- print("[大乱斗] quick battle result", waveData.win, waveData.win == true and 1 or 2)
                self:SetTeamBattleState(i, waveData.win == true and 1 or 2)
            end
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.05))
        self:SetTotalBattleResult()
        self:ShowExitBtn()

        self.showCo = nil
    end)
end

function LadderStruggleBattleAbstractDialog:ShowBattleInFixedDuration(duration)
    self:ShowExitBtn()
    self:SetTotalBattleState(BattleState.Running)
    
    self.showCo = cs_coroutine.start(function()
        local deadLists = LadderStruggleMgr.deadLists
        local totalDeadCount = 0
        for i, deadList in ipairs(deadLists) do
            totalDeadCount = totalDeadCount + #deadList
        end

        local waitTime = duration / totalDeadCount

        local struggleData = LadderStruggleMgr.struggleData
        for i, waveData in ipairs(struggleData) do
            if i > LadderStruggleMgr.totalSessionCount then
                self:SetTeamBattleState(i, 3)
            else
                self.curWave = i
                local deadList = deadLists[i]
                for i, id in ipairs(deadList) do
                    Events.Broadcast(Constants.EventNames.UIQuickBattleRoleDead, id)
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(waitTime))
                end
                self:SetTeamBattleState(i, waveData.win == true and 1 or 2)
            end
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.05))
        self:SetTotalBattleResult()

        self.showCo = nil
    end)
end

function LadderStruggleBattleAbstractDialog:SetTotalBattleResult()
    local scoreL = LadderStruggleMgr.scoreL
    local scoreR = LadderStruggleMgr.scoreR
    self:SetTotalBattleState(scoreL > scoreR and BattleState.Win or BattleState.Lose)
    self:SetScore(scoreL, scoreR)
    if scoreL > scoreR
    and not self.noSwapAnimation then
        self:PlayWinAnimation()
    end
end

function LadderStruggleBattleAbstractDialog:SetTeamBattleResult()
    local struggleData = LadderStruggleMgr.struggleData
    for i, waveData in ipairs(struggleData) do
        if i > LadderStruggleMgr.totalSessionCount then
            self:SetTeamBattleState(i, 3)
        else
            if not isNull(waveData.aliveData) then
                self:SetTeamAliveState(i, waveData.aliveData.L, waveData.aliveData.R)
            end
            self:SetTeamBattleState(i, waveData.win == true and 1 or 2)
        end
    end
end

--- 卡牌死亡时的表现
---@param id any
function LadderStruggleBattleAbstractDialog:OnRoleDead(id)
    local waveData = LadderStruggleMgr.struggleData[self.curWave]
    local initData = waveData.initData
    for i, roleInfo in ipairs(initData.playerTeam[1]) do
        if roleInfo.id == id then
            self:SetTeamMemberAliveState(self.curWave, 1, {index = i, state = 0})
            return
        end
    end
    for i, roleInfo in ipairs(initData.enemyTeam[1]) do
        if roleInfo.id == id then
            self:SetTeamMemberAliveState(self.curWave, 2, {index = i, state = 0})
            return
        end
    end
end

function LadderStruggleBattleAbstractDialog:GetStatisticData()
    -- 如果只进行了2场战斗，就剔除第3场的战斗统计
    local data = DeepCopy(LadderStruggleMgr.struggleStatistics)
    -- print("[大乱斗] 统计数据", table.dump(data, nil, 2))
    if LadderStruggleMgr.totalSessionCount == 2 then
        data["3"] = nil
        data[3] = nil
    end
    return data
end

function LadderStruggleBattleAbstractDialog:ShowExitBtn()
    if isNotNull(self.co_rankUp) then
        self.waitCo = cs_coroutine.start(function()
            while isNotNull(self.co_rankUp) do
                cs_coroutine.yield_return()
            end
            KTool.SetActive(self.RT_ExitBtn, true)
            self.waitCo = nil
        end)
    else
        KTool.SetActive(self.RT_ExitBtn, true)
    end
end

function LadderStruggleBattleAbstractDialog:PlayWinAnimation()
    local playerInfoList = LadderStruggleMgr:GetPlayerInfoList()
    local myRank = checkNumber(playerInfoList[1].ranking)
    local otherRank = checkNumber(playerInfoList[2].ranking)
    local rankChange = myRank > otherRank
    local rankDiff = myRank - otherRank
    if not rankChange then
        self.Animator_Result:Play("Win")
    else
        local myRankCell = GetLuaBehaviour(self.RT_MyRankCell.gameObject, RankCellLuaPath).Env
        local otherRankCell = GetLuaBehaviour(self.RT_OtherRankCell.gameObject, RankCellLuaPath).Env
        myRankCell:UpdatePlayerInfo(playerInfoList[1])
        myRankCell:SetRankDiff(rankDiff)
        otherRankCell:UpdatePlayerInfo(playerInfoList[2])
        self.Animator_Result:Play("WinUp")
        self.co_rankUp = cs_coroutine.start(function()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.167))
            myRankCell:AnimateRankChange(otherRank, 0.3)
            otherRankCell:AnimateRankChange(myRank, 0.3)
            self.co_rankUp = nil
        end)
    end
end

return LadderStruggleBattleAbstractDialog


